    h,w=len(g),len(g[0]); bg=g[0][0]
    S=lambda a,b: 0<=a<h and 0<=b<w and g[a][b]!=bg
    out=[r[:] for r in g]
    for i in range(h):
        for j in range(w):
            if g[i][j]!=bg: continue
            hit=False
            for di,dj in ((0,1),(0,-1),(1,0),(-1,0)):
                k=1
                while True:
                    a,b=i+di*k,j+dj*k
                    if not (0<=a<h and 0<=b<w): break
                    if g[a][b]!=bg:
                        if S(a+di,b+dj): hit=True
                        break
                    k+=1
            if hit: out[i][j]=2
    return out
